import 'package:flutter/material.dart';
import '../services/component3_api.dart';
import 'negotiation_screen.dart';
class PurchaseOfferScreen extends StatefulWidget{final int propertyId;const PurchaseOfferScreen({super.key,required this.propertyId});@override State<PurchaseOfferScreen> createState()=>_PurchaseOfferScreenState();}
class _PurchaseOfferScreenState extends State<PurchaseOfferScreen>{final api=Component3Api();final amount=TextEditingController();final conditions=TextEditingController();bool saving=false;Future<void>submit()async{final value=double.tryParse(amount.text.trim());if(value==null){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Enter a valid offer amount.')));return;}setState(()=>saving=true);try{final offer=await api.createPurchaseOffer(propertyListingId:widget.propertyId,offerAmount:value,conditions:conditions.text.trim().isEmpty?null:conditions.text.trim());if(mounted)Navigator.pushReplacement(context,MaterialPageRoute(builder:(_)=>Component3NegotiationScreen(rental:false,transactionId:offer.id,title:'Purchase negotiation #${offer.id}')));}catch(e){ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.toString())));}finally{if(mounted)setState(()=>saving=false);}}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Make Purchase Offer')),body:ListView(padding:const EdgeInsets.all(20),children:[TextField(controller:amount,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Offer amount',border:OutlineInputBorder())),const SizedBox(height:14),TextField(controller:conditions,maxLines:5,decoration:const InputDecoration(labelText:'Conditions',border:OutlineInputBorder())),const SizedBox(height:18),ElevatedButton(onPressed:saving?null:submit,child:Text(saving?'Submitting...':'Submit Offer'))]));}
